# Clean, deduplicate, and remove cross-chapter overlaps
clean_ch11 = []
seen_local = set()

for word, meaning, example in raw_religion_words:
    w_clean = word.upper().replace(" ", "").replace("-", "")
    if w_clean in used_words:
        print(f"Skipping overlap word: {w_clean}")
        continue
    if w_clean in seen_local:
        print(f"Skipping duplicate in raw list: {w_clean}")
        continue
    seen_local.add(w_clean)
    clean_ch11.append({
        "word": w_clean,
        "meaning": meaning,
        "example": example
    })

print(f"Total raw words prepared: {len(raw_religion_words)}")
print(f"Total valid unique Ch11 words: {len(clean_ch11)}")

assert len(clean_ch11) >= 364, f"Need at least 364 words, got {len(clean_ch11)}"

# Trim to exactly 364 words
clean_ch11 = clean_ch11[:364]

os.makedirs("scratch", exist_ok=True)
with open("scratch/chapter_11_clean_words.json", "w", encoding="utf-8") as f:
    json.dump(clean_ch11, f, indent=2)

